def days_for(cls):
    out = []
    for r in range(4):
        for art in RHYTHM:
            p = ARTS[cls][art][r]
            need = NEED[art] + (p[2] if len(p) > 2 else [])
            out.append((f"{art}: {p[0]}", p[1], "", need))
    return out

BLOCKS = {cls: [{'subj': 'wart', 'title': f"Arts and handwork · Class {cls}", 'weeks': 4,
                 'summary': f"The weekly Waldorf arts rhythm for Class {cls}: wet-on-wet watercolour painting, handwork, music, modelling, and craft or baking. Each art comes back every week, growing a little each time. These lessons educate the hands and the feelings as the main lesson educates the head.",
                 'goal_line': "Hands, heart and head learn together.",
                 'goals': ["take part in each art of the week with care", "finish a handwork project", "sing and play simple music", "model and paint without fear of mistakes"],
                 'words': [("wet-on-wet", "painting on wet paper so colours flow"), ("handwork", "making useful things by hand"), ("pentatonic", "music with five notes")],
                 'need': ["an apron", "a cloth to protect the table"], 'practice': [("", "")], 'days': days_for(cls)} ] for cls in ARTS}
